import React, { useEffect, useState } from 'react';
import { FileText, Download } from 'lucide-react';
import api from '../services/api';

export default function PortalMateriais() {
  const [materiais, setMateriais] = useState([]);
  const [loading, setLoading] = useState(true);
  const [erro, setErro] = useState('');

  useEffect(() => {
    api.get('/materiais/recebidos')
      .then((res) => setMateriais(res.data))
      .catch(() => setErro('Erro ao carregar materiais.'))
      .finally(() => setLoading(false));
  }, []);

  if (loading) return <div className="loading"><div className="spinner" /></div>;

  return (
    <div className="page-container">
      <div className="page-header">
        <h2><FileText size={22} style={{ verticalAlign: 'middle', marginRight: 8 }} />Materiais Didáticos</h2>
        <p style={{ color: 'var(--cinza)' }}>Aqui estão os materiais enviados pelos seus professores.</p>
      </div>

      {erro && <div className="alert alert-error" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <span>{erro}</span>
      </div>}

      {materiais.length === 0 ? (
        <div className="card empty-state">
          <FileText size={56} />
          <h3>Nenhum material disponível</h3>
          <p>Os materiais didáticos dos seus professores aparecerão aqui quando forem enviados.</p>
        </div>
      ) : (
        <div className="card" style={{ padding: 0 }}>
          <table className="table">
            <thead>
              <tr>
                <th>Título</th>
                <th>Turma</th>
                <th>Disciplina</th>
                <th>Professor</th>
                <th>Data</th>
                <th>Download</th>
              </tr>
            </thead>
            <tbody>
              {materiais.map((item) => (
                <tr key={item.id}>
                  <td><strong>{item.titulo}</strong></td>
                  <td>{item.turma_nome || 'Geral'}</td>
                  <td>{item.disciplina_nome || 'Geral'}</td>
                  <td>{item.professor_nome || '—'}</td>
                  <td>{new Date(item.criado_em).toLocaleDateString('pt-BR')}</td>
                  <td>
                    <a className="btn btn-outline btn-sm" href={`/uploads/materiais/${item.caminho}`} target="_blank" rel="noreferrer">
                      <Download size={14} /> Abrir
                    </a>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
